// Ported from legacy/RAWR_WotLK_3.3.5a/Rawr.TankDK/Weapon.cs @ 46f190bee32964cc8df5fe853d95b8a343f5aa23
package rawr.models.tankdk;

import rawr.base.character.CharacterClass;
import rawr.base.items.Item;
import rawr.base.stats.StatConversion;
import rawr.base.stats.Stats;

public class Weapon {
    public float baseSpeed;
    public float baseDamage;
    /** Speed of the weapon after haste has been applied. */
    public float hastedSpeed;
    public float mitigation;
    public float effectiveExpertise;
    public float chanceDodged;
    /** Damage per second generated by the weapon after AP modifiers and haste. */
    public float DPS;
    /** Damage per hit generated by the weapon after AP modifiers. */
    public float damage;

    public Weapon(Item i, Stats stats, CalculationOptionsTankDK calcOpts, float expertise) {
        if (stats == null || calcOpts == null || calcOpts.getTalents() == null) {
            // Missing necessary pieces.
            return;
        }

        if (i == null) {
            i = new Item();
            i.setSpeed(2f);
            i.setMinDamage(0);
            i.setMaxDamage(0);
        }

        // Ensure that the weapon that does damage has some sort of speed associated.
        if ((i.getMinDamage() > 0 || i.getMaxDamage() > 0) && i.getSpeed() == 0) {
            i.setSpeed(2f);
        }

        effectiveExpertise = stats.getExpertise();
        float fightDuration = calcOpts.getFightLength() * 60f;

        baseSpeed = i.getSpeed();
        baseDamage = (float) (i.getMinDamage() + i.getMaxDamage()) / 2f + stats.getWeaponDamage();

        // Attack Speed
        {
            hastedSpeed = baseSpeed / (1f + (StatConversion.getHasteFromRating(stats.getHasteRating(), CharacterClass.DeathKnight)) + stats.getPhysicalHaste());
            hastedSpeed /= 1f + 0.05f * (float) calcOpts.getTalents().getImprovedIcyTalons();

            if (calcOpts.getBloodlust()) {
                float numLust = fightDuration % 300f;  // bloodlust changed in 3.0, can only have one every 5 minutes.
                float fullLustDur = (numLust - 1) * 300f + 40f;
                if (fightDuration < fullLustDur) // if the last lust doesn't go its full duration
                {
                    float lastLustFraction = (fullLustDur - fightDuration) / 40f;
                    numLust -= 1f;
                    numLust += lastLustFraction;
                }

                float bloodlustUptime = (numLust * 40f) / fightDuration;

                hastedSpeed /= 1f + (0.3f * bloodlustUptime);
            }
        }

        // Dodge
        {
            chanceDodged = StatConversion.WHITE_DODGE_CHANCE_CAP[calcOpts.getTargetLevel() - 80];
            // Changing this to use the statconversion formula like Target Dodge%;
            chanceDodged -= StatConversion.getDodgeParryReducFromExpertise(stats.getExpertise());
            if (chanceDodged < 0f) chanceDodged = 0f;
        }

        // White Damage
        {
            // White damage per hit.  Basic white hits are used elsewhere.
            damage = baseDamage + (stats.getAttackPower() / 14f) * baseSpeed;
            DPS = 0f;
            if (hastedSpeed > 0) {
                DPS = damage / hastedSpeed;
            }
        }
    }
}
